corrected_code:
const express = require('express');
const rateLimit = require('express-rate-limit');
const db = require('../db');

const app = express();
app.set('trust proxy', false);

const challengeLimiter = rateLimit({
  windowMs: 10 * 60 * 1000,
  max: 10,
  keyGenerator: (req) => req.ip
});

app.post('/api/customers/:customerId/security-challenge', challengeLimiter, async (req, res) => {
  const { customerId } = req.params;

  // Validate that the request corresponds to the authenticated customer session
  if (!req.session || req.session.customerId !== customerId) {
    return res.status(403).json({ error: 'Unauthorized challenge access' });
  }

  const customer = await db('customers').where({ id: customerId }).first();
  if (!customer) {
    return res.status(404).json({ error: 'Customer not found' });
  }

  return res.json({
    customerId: customer.id,
    securityQuestion: customer.security_question_prompt
  });
});

module.exports = app;
